pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        // Keep the caller address admissible (non-zero, not precompile to be safe)
        vm.assume(caller != address(0));
        // Ensure the caller has enough Ether to send the fuzzed amount
        vm.deal(caller, amount);

        // Record initial balance
        uint256 beforeBalance = c.getBalance(caller);

        // Try the addToBalance call. If it overflows, the correct contract (C) will revert;
        // the buggy one will wrap silently and not revert.
        bool ok;
        vm.prank(caller);
        try c.addToBalance{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // If the call succeeded, the new balance must equal the old balance plus the amount.
            // This holds in both the correct and buggy version for non-overflow amounts.
            // For overflow amounts (beforeBalance + amount > type(uint256).max),
            // the correct contract reverts (so this branch is unreachable),
            // but the buggy contract allows it and breaks the invariant.
            uint256 afterBalance = c.getBalance(caller);
            assertTrue(afterBalance == beforeBalance + amount);
        }
    }
}

