        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.deal(actor, amount);
        uint256 prevBalance = c.getBalance(actor);
        vm.prank(actor);
        bool ok = true;
        try c.addToBalance{value: amount}() {
            ok = true;
        } catch {
