pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 reenterAttempts, address target) public {
        // Keep amounts reasonable but wide
        depositAmount = bound(depositAmount, 1, 100 ether);
        reenterAttempts = bound(reenterAttempts, 1, 5);
        // Ensure target is not the C contract itself to avoid selfdestruct etc., keep it wide
        vm.assume(target != address(c) && target != address(0) && target.code.length == 0);

        // Deploy a re-entrant attacker that calls withdrawBalance in its receive
        ReenterAttacker attacker = new ReenterAttacker(address(c), reenterAttempts);
        address reentrant = address(attacker);

        // Fund the reentrant account with depositAmount Ether
        vm.deal(reentrant, depositAmount);
        // Make the reentrant deposit into C
        vm.prank(reentrant);
        c.addToBalance{value: depositAmount}();

        // Record the attacker's balance in C before withdrawal (should equal depositAmount)
        uint256 preWithdrawC = c.getBalance(reentrant);

        // Prank the reentrant to call withdrawBalance
        vm.prank(reentrant);
        c.withdrawBalance();

        // After the whole call, the C balance for the attacker must be 0 (reference)
        // The buggy version leaves the balance unchanged (or higher), violating this.
        uint256 postWithdrawC = c.getBalance(reentrant);
        assertTrue(postWithdrawC == 0);
    }
}

contract ReenterAttacker {
    C public target;
    uint256 public reentriesLeft;
    uint256 public constant REENTER_AMOUNT = 1 wei; // minimal to not run out of funds

    constructor(C _target, uint256 _reentries) {
        target = _target;
        reentriesLeft = _reentries;
    }

    receive() external payable {
        if (reentriesLeft > 0 && address(target).balance >= REENTER_AMOUNT) {
            reentriesLeft--;
            target.withdrawBalance();
        }
    }
}

