pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 reenterAttempts) public {
        // Keep reentry attempts positive but bounded to avoid out-of-gas
        vm.assume(reenterAttempts > 0 && reenterAttempts <= 5);
        // Ensure deposit can cover all attempted withdrawals
        uint256 needed = depositAmount * reenterAttempts;
        vm.assume(depositAmount > 0 && needed <= type(uint256).max / 2);

        // Deploy attacker that will re-enter on receive
        ReenterAttacker attacker = new ReenterAttacker(address(c), reenterAttempts);
        vm.deal(address(attacker), needed);

        // Attacker deposits and then withdraws (triggers reentrancy)
        attacker.attack(depositAmount);

        // Invariant: contract ETH balance must equal sum of all user balances
        uint256 attackerBalance = c.getBalance(address(attacker));
        uint256 otherBalance = c.getBalance(address(this));
        uint256 totalBalances = attackerBalance + otherBalance;
        uint256 contractBalance = address(c).balance;
        assertTrue(totalBalances == contractBalance);
    }
}

contract ReenterAttacker {
    C public target;
    uint256 public remainingReentries;

    constructor(address _target, uint256 _reentries) {
        target = C(_target);
        remainingReentries = _reentries;
    }

    function attack(uint256 amount) external payable {
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
    }

    receive() external payable {
        if (remainingReentries > 0) {
            remainingReentries--;
            target.withdrawBalance();
        }
    }
}

