pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, address addr1, address addr2) public {
        vm.assume(actor != addr1 && actor != addr2 && addr1 != addr2);
        vm.assume(addr1 != address(c) && addr2 != address(c) && actor != address(c));
        vm.assume(amount > 0);

        // Fund and add balance for actor
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // Possibly add balance for addr1 and addr2 to create other non-zero balances
        if (amount > 1) {
            vm.deal(addr1, amount);
            vm.prank(addr1);
            c.addToBalance{value: amount}();
        }
        if (amount > 2) {
            vm.deal(addr2, amount);
            vm.prank(addr2);
            c.addToBalance{value: amount}();
        }

        // Record sum of known user balances + contract balance before withdrawal
        uint256 sumBefore = c.getBalance(actor) + c.getBalance(addr1) + c.getBalance(addr2) + address(c).balance;

        // Actor withdraws
        bool ok;
        vm.prank(actor);
        try c.withdrawBalance() { ok = true; } catch { ok = false; }

        if (ok) {
            // After a successful withdrawal, the invariant sum must hold
            uint256 sumAfter = c.getBalance(actor) + c.getBalance(addr1) + c.getBalance(addr2) + address(c).balance;
            assertTrue(sumBefore == sumAfter);
        } else {
            // If withdrawal reverted, balances remain unchanged, so invariant trivially holds
            assertTrue(true);
        }
    }
}

