        vm.prank(address(attacker));
        attacker.attack();

        // After withdrawBalance completes, the attacker's userBalance should reflect the re-entrant deposit,
        // because the contract effects: read balance, zero, send, (bug: zero again).
        // The reference C only zeros once (before send), so the re-entrant deposit survives.
