pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(depositAmount >= withdrawAmount);

        // Deposit funds for caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.addToBalance{value: depositAmount}();

        // Record caller's balance before withdraw
        uint256 callerBalanceBefore = c.getBalance(caller);

        // Now the caller withdraws a portion
        vm.prank(caller);
        try c.withdrawBalance() returns (bytes memory) {
            // Success - measure state
        } catch {
            // If withdrawBalance reverts, we skip the invariant check.
            return;
        }

        // After a non-reverting withdrawBalance, the contract's ETH balance
        // must be at least the sum of all userBalance entries for addresses
        // that still hold a balance. Since only the caller changed, we can
        // compute the expected total balance stored.
        // However, we need a general invariant: total supply of ETH held
        // across all balances equals the contract's balance.
        // We can iterate over known addresses? No – userBalance is private
        // and there's no getter for all keys. So we must craft an invariant
        // that the public surface can check.
        //
        // Instead, we note: withdrawBalance clears userBalance[caller] and
        // sends that amount. So after a successful call:
        //   address(c).balance >= sum of all userBalance entries.
        // Because we only know the caller's entry, we verify a weaker but
        // still general property: the caller's balance after withdraw must be 0,
        // and the contract's balance must reflect the sent amount.
        //
        // The buggy version sets balance to 0 but sends 0 ETH. Therefore
        // we can assert: after a successful withdrawBalance, the caller's
        // new balance is exactly 0 and address(c).balance equals
        // (initial contract balance - callerBalanceBefore).
        //
        // That property holds for the correct version and fails when
        // the contract steals the funds (sends 0).
        assertTrue(
            c.getBalance(caller) == 0 &&
            address(c).balance == depositAmount - callerBalanceBefore
        );
    }
}

